// C trace header dependencies supplied by the surrounding translation unit:
// linux/byteorder/generic.h, linux/tracepoint.h, linux/trace_seq.h,
// ../common.h, and internal.h.

// The following enum-list expansions are generated by the corresponding
// MHI_*_LIST definitions in the dependent headers.
// mhi_state(a, b)      => TRACE_DEFINE_ENUM!(MHI_STATE_##a);
// mhi_state_end(a, b)  => TRACE_DEFINE_ENUM!(MHI_STATE_##a);
// mhi_pm_state(a, b)   => TRACE_DEFINE_ENUM!(MHI_PM_STATE_##a);
// mhi_pm_state_end(a,b)=> TRACE_DEFINE_ENUM!(MHI_PM_STATE_##a);
// mhi_ee(a, b)         => TRACE_DEFINE_ENUM!(MHI_EE_##a);
// mhi_ee_end(a, b)     => TRACE_DEFINE_ENUM!(MHI_EE_##a);
// ch_state_type(a, b)  => TRACE_DEFINE_ENUM!(MHI_CH_STATE_TYPE_##a);
// ch_state_type_end(a,b)=> TRACE_DEFINE_ENUM!(MHI_CH_STATE_TYPE_##a);
// dev_st_trans(a, b)   => TRACE_DEFINE_ENUM!(DEV_ST_TRANSITION_##a);
// dev_st_trans_end(a,b)=> TRACE_DEFINE_ENUM!(DEV_ST_TRANSITION_##a);

// The alternate list forms produce symbolic-value pairs:
// { MHI_STATE_##a, b }, { MHI_PM_STATE_##a, b }, { MHI_EE_##a, b },
// { MHI_CH_STATE_TYPE_##a, b }, and { DEV_ST_TRANSITION_##a, b }.

macro_rules! TPS {
    ($x:expr) => { tracepoint_string!($x) };
}

TRACE_EVENT!(mhi_gen_tre,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, mhi_chan: *mut mhi_chan,
              mhi_tre: *mut mhi_ring_element),
    TP_ARGS!(mhi_cntrl, mhi_chan, mhi_tre),
    TP_STRUCT__entry!(
        __string!(name, (*mhi_cntrl).mhi_dev.name),
        __field!(i32, ch_num),
        __field!(*mut core::ffi::c_void, wp),
        __field!(u64, tre_ptr),
        __field!(u32, dword0),
        __field!(u32, dword1)
    ),
    TP_fast_assign!({
        __assign_str!(name);
        __entry.ch_num = (*mhi_chan).chan;
        __entry.wp = mhi_tre as *mut core::ffi::c_void;
        __entry.tre_ptr = le64_to_cpu((*mhi_tre).ptr);
        __entry.dword0 = le32_to_cpu((*mhi_tre).dword[0]);
        __entry.dword1 = le32_to_cpu((*mhi_tre).dword[1]);
    }),
    TP_printk!("%s: Chan: %d TRE: 0x%p TRE buf: 0x%llx DWORD0: 0x%08x DWORD1: 0x%08x\n",
        __get_str!(name), __entry.ch_num, __entry.wp, __entry.tre_ptr,
        __entry.dword0, __entry.dword1)
);

TRACE_EVENT!(mhi_intvec_states,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, dev_ee: i32, dev_state: i32),
    TP_ARGS!(mhi_cntrl, dev_ee, dev_state),
    TP_STRUCT__entry!(
        __string!(name, (*mhi_cntrl).mhi_dev.name),
        __field!(i32, local_ee), __field!(i32, state),
        __field!(i32, dev_ee), __field!(i32, dev_state)
    ),
    TP_fast_assign!({
        __assign_str!(name);
        __entry.local_ee = (*mhi_cntrl).ee;
        __entry.state = (*mhi_cntrl).dev_state;
        __entry.dev_ee = dev_ee;
        __entry.dev_state = dev_state;
    }),
    TP_printk!("%s: Local EE: %s State: %s Device EE: %s Dev State: %s\n",
        __get_str!(name), __print_symbolic!(__entry.local_ee, MHI_EE_LIST),
        __print_symbolic!(__entry.state, MHI_STATE_LIST),
        __print_symbolic!(__entry.dev_ee, MHI_EE_LIST),
        __print_symbolic!(__entry.dev_state, MHI_STATE_LIST))
);

TRACE_EVENT!(mhi_tryset_pm_state,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, pm_state: i32),
    TP_ARGS!(mhi_cntrl, pm_state),
    TP_STRUCT__entry!(__string!(name, (*mhi_cntrl).mhi_dev.name), __field!(i32, pm_state)),
    TP_fast_assign!({
        __assign_str!(name);
        if pm_state != 0 { pm_state = __fls(pm_state); }
        __entry.pm_state = pm_state;
    }),
    TP_printk!("%s: PM state: %s\n", __get_str!(name),
        __print_symbolic!(__entry.pm_state, MHI_PM_STATE_LIST))
);

DECLARE_EVENT_CLASS!(mhi_process_event_ring,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, rp: *mut mhi_ring_element),
    TP_ARGS!(mhi_cntrl, rp),
    TP_STRUCT__entry!(
        __string!(name, (*mhi_cntrl).mhi_dev.name), __field!(u32, dword0),
        __field!(u32, dword1), __field!(i32, state), __field!(u64, ptr),
        __field!(*mut core::ffi::c_void, rp)
    ),
    TP_fast_assign!({
        __assign_str!(name); __entry.rp = rp as *mut core::ffi::c_void;
        __entry.ptr = le64_to_cpu((*rp).ptr);
        __entry.dword0 = le32_to_cpu((*rp).dword[0]);
        __entry.dword1 = le32_to_cpu((*rp).dword[1]);
        __entry.state = MHI_TRE_GET_EV_STATE!(rp);
    }),
    TP_printk!("%s: TRE: 0x%p TRE buf: 0x%llx DWORD0: 0x%08x DWORD1: 0x%08x State: %s\n",
        __get_str!(name), __entry.rp, __entry.ptr, __entry.dword0,
        __entry.dword1, __print_symbolic!(__entry.state, MHI_STATE_LIST))
);

DEFINE_EVENT!(mhi_process_event_ring, mhi_data_event,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, rp: *mut mhi_ring_element), TP_ARGS!(mhi_cntrl, rp));
DEFINE_EVENT!(mhi_process_event_ring, mhi_ctrl_event,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, rp: *mut mhi_ring_element), TP_ARGS!(mhi_cntrl, rp));

DECLARE_EVENT_CLASS!(mhi_update_channel_state,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, mhi_chan: *mut mhi_chan,
              state: i32, reason: *const core::ffi::c_char),
    TP_ARGS!(mhi_cntrl, mhi_chan, state, reason),
    TP_STRUCT__entry!(
        __string!(name, (*mhi_cntrl).mhi_dev.name), __field!(i32, ch_num),
        __field!(i32, state), __field!(*const core::ffi::c_char, reason)
    ),
    TP_fast_assign!({
        __assign_str!(name); __entry.ch_num = (*mhi_chan).chan;
        __entry.state = state; __entry.reason = reason;
    }),
    TP_printk!("%s: chan%d: %s state to: %s\n", __get_str!(name),
        __entry.ch_num, __entry.reason,
        __print_symbolic!(__entry.state, MHI_CH_STATE_TYPE_LIST))
);

DEFINE_EVENT!(mhi_update_channel_state, mhi_channel_command_start,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, mhi_chan: *mut mhi_chan, state: i32,
              reason: *const core::ffi::c_char), TP_ARGS!(mhi_cntrl, mhi_chan, state, reason));
DEFINE_EVENT!(mhi_update_channel_state, mhi_channel_command_end,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, mhi_chan: *mut mhi_chan, state: i32,
              reason: *const core::ffi::c_char), TP_ARGS!(mhi_cntrl, mhi_chan, state, reason));

TRACE_EVENT!(mhi_pm_st_transition,
    TP_PROTO!(mhi_cntrl: *mut mhi_controller, state: i32),
    TP_ARGS!(mhi_cntrl, state),
    TP_STRUCT__entry!(__string!(name, (*mhi_cntrl).mhi_dev.name), __field!(i32, state)),
    TP_fast_assign!({ __assign_str!(name); __entry.state = state; }),
    TP_printk!("%s: Handling state transition: %s\n", __get_str!(name),
        __print_symbolic!(__entry.state, DEV_ST_TRANSITION_LIST))
);

